// Combine targets by numeric skill ID for presentation, preserving raw history.
internal sealed class DpsSkillSummary {
    internal DpsSkillTotal Raw;
    public string Skill {get;set;}public long Amount {get;set;}public double Share {get;set;}public int Impacts {get;set;}public double? CriticalRate {get;set;}public uint? Peak {get;set;}
    internal static List<DpsSkillSummary> Build(DpsHistoryPlayer player,string view,string language){
        var result=new List<DpsSkillSummary>();if(player==null||player.Skills==null)return result;var groups=new Dictionary<uint,DpsSkillTotal>();
        foreach(var source in player.Skills){DpsSkillTotal sum;if(!groups.TryGetValue(source.SkillId,out sum)){groups[source.SkillId]=source.Copy();continue;}
            sum.Damage+=source.Damage;sum.PeriodicDamage+=source.PeriodicDamage;sum.Healing+=source.Healing;sum.HealingReceived+=source.HealingReceived;sum.DamagePrimary+=source.DamagePrimary;sum.DamageCritical+=source.DamageCritical;sum.HealingPrimary+=source.HealingPrimary;sum.HealingCritical+=source.HealingCritical;sum.ReceivedPrimary+=source.ReceivedPrimary;sum.ReceivedCritical+=source.ReceivedCritical;
            sum.EligibleDamageImpacts+=source.EligibleDamageImpacts;sum.DirectImpacts+=source.DirectImpacts;sum.PeriodicTicks+=source.PeriodicTicks;sum.Criticals+=source.Criticals;sum.HealingEvents+=source.HealingEvents;sum.HealingCriticals+=source.HealingCriticals;sum.ReceivedEvents+=source.ReceivedEvents;sum.ReceivedCriticals+=source.ReceivedCriticals;sum.HealingTicks+=source.HealingTicks;sum.ReceivedTicks+=source.ReceivedTicks;sum.HighestHit=Math.Max(sum.HighestHit,source.HighestHit);
        }
        long total=DpsEncounterDetails.Amount(player,view);foreach(var sum in groups.Values){long amount=view=="healing"?sum.Healing:view=="received"?sum.HealingReceived:sum.Damage;if(amount==0)continue;int eligible=view=="healing"?sum.HealingEvents:view=="received"?sum.ReceivedEvents:sum.EligibleDamageImpacts,critical=view=="healing"?sum.HealingCriticals:view=="received"?sum.ReceivedCriticals:sum.Criticals;
            result.Add(new DpsSkillSummary{Raw=sum,Skill=SkillCatalogue.Shared.Name(sum.SkillId,language),Amount=amount,Share=total>0?100.0*amount/total:0,Impacts=view=="healing"?sum.HealingTicks:view=="received"?sum.ReceivedTicks:sum.DirectImpacts+sum.PeriodicTicks,CriticalRate=eligible>0?(double?)(100.0*critical/eligible):null,Peak=view=="damage"&&sum.HighestHit>0?(uint?)sum.HighestHit:null});
        }result.Sort(delegate(DpsSkillSummary a,DpsSkillSummary b){return b.Amount.CompareTo(a.Amount);});return result;
    }
}

