=TextAlignment.Right;Grid.SetColumn(amount,2);row.Children.Add(amount);var hit=new Border{Child=row,Padding=new Thickness(0,3,0,3),Background=Brushes.Transparent,Cursor=System.Windows.Input.Cursors.Hand};hit.MouseLeftButtonUp+=delegate{SelectPlayer(actor);};chart.Children.Add(hit);}if(visible.Count==0)chart.Children.Add(SettingsVisual.Text("No combat data yet.",12,"#929CAD"));}
