    DpsHistoryPlayer Player(){foreach(var p in visible)if(p.Actor==selectedActor)return p;return null;}
    static string Number(object value){return value==null?"—":value is double?((double)value).ToString("N1",CultureInfo.InvariantCulture):value is long?((long)value).ToString("N0",CultureInfo.InvariantCulture):value is uint?((uint)value).ToString("N0",CultureInfo.InvariantCulture):Convert.ToString(value,CultureInfo.InvariantCulture);}
    void Stat(Panel panel,string title,object value,string tooltip=null){var stack=new StackPanel();var label=SettingsVisual.Text(T(title),11,"#929CAD");label.ToolTip=tooltip==null?null:T(tooltip);stack.Children.Add(label);stack.Children.Add(SettingsVisual.Text(Number(value),panel==cards?18:13));var card=SettingsVisual.Card(stack,new Thickness(10,8,10,8));card.Margin=new Thickness(0,0,6,6);if(panel!=cards)card.Width=176;panel.Children.Add(card);}
