internal sealed class DpsCombatPane:Grid {
    readonly EnergyOverlay owner;readonly DpsEncounterDetails details;long revision=-1;string language,style;
    internal DpsCombatPane(EnergyOverlay parent){owner=parent;details=new DpsEncounterDetails(parent,delegate(string view){var c=owner.Configuration;c.Dps.View=view;owner.ApplyConfiguration(c);});var scroll=new ScrollViewer{Content=details,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Background=Brushes.Transparent};scroll.SetResourceReference(FrameworkElement.StyleProperty,"SlimScroll");details.Margin=new Thickness(0,0,10,0);Children.Add(scroll);}
    internal void Refresh(bool force=false){if(!force&&!IsVisible)return;var o=owner.Configuration.Dps;string next=o.View+o.ShowSelfAsYou+o.DamageColor+o.HealerColor+o.TankColor+o.Color;long current=owner.CombatSkillRevision;if(!force&&current==revision&&language==owner.Language&&next==style)return;revision=current;language=owner.Language;style=next;details.Set(owner.CombatAnalysis,null,o.View);}
    internal void Verify(){details.Verify();}
    internal void VerifyVisibleLayout(){details.VerifyVisibleLayout();}
}
